window.MOTIF_CATALOG_CHUNKS[28]={"cards":[{"id":"MEJE-KW-002897","row_version":1,"title":"배우의 외모를 낮춰 보이는 분장","original":"Beauty Inversion","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"매력적인 이미지로 알려진 배우에게 거친 분장과 조명을 입혀 다른 인물처럼 보이게 한다. 연기의 평가가 외형의 변화에 과하게 기대는지 살핀다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-002897/index.html"},{"id":"MEJE-KW-002898","row_version":2,"title":"아름다운 인물을 악하다고 여기는 관습","original":"Beauty Is Bad","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"눈에 띄는 매력을 계산적이고 위험한 성격의 징표처럼 사용한다. 아름다움과 도덕성을 자동으로 연결한다는 점에서 반대 방향의 편견과 같다. 아름다운 인물을 선하다고 여기는 관습와 선악 판단의 방향만 바뀐 외모 편견이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002898/index.html"},{"id":"MEJE-KW-002899","row_version":1,"title":"아름다움을 다른 능력보다 우선하기","original":"Beauty Is Best","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"인물이나 사회가 기술과 인격보다 외모의 가치를 앞세운다. 누구의 선택이 제한되는지 보면 아름다움의 규범이 작동하는 자리를 알 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-002899/index.html"},{"id":"MEJE-KW-002900","row_version":2,"title":"여성 전투원의 상처를 남기지 않기","original":"Beauty Is Never Tarnished","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"격렬하게 싸운 여성 인물이 남성 동료와 달리 피부와 옷차림을 거의 흐트러뜨리지 않는다. 전투의 대가보다 보기 좋은 외형을 우선하는 화면의 규칙이다. 상처를 보기 좋게 바꾸는 화면은 울음마저 아름답게 보이도록 연출하기의 눈물 연출과 닮는다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002900/index.html"},{"id":"MEJE-KW-002901","row_version":2,"title":"아름다움의 기준이 사람마다 다르기","original":"Beauty Is Relative","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"한 인물을 두고도 문화와 경험에 따라 매력을 다르게 느낀다. 모두가 한 기준에 동의하는 세계와 다른 관계를 만든다. 외모를 심사하는 대회의 기준도 관객과 참가자에 따라 다르게 받아들일 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002901/index.html"},{"id":"MEJE-KW-002902","row_version":2,"title":"외모를 잃자 삶이 뒤집히기","original":"Beauty to Beast","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"아름답다고 인정받던 인물이 변한 외형 때문에 관계와 지위의 변화를 겪는다. 외모가 인간의 가치라는 전제를 드러내거나 흔드는 전개다. 꾸밈을 통해 시선이 달라지는 꾸밈을 바꾸자 뒤늦게 아름답다고 알아보기와 반대의 전개다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002902/index.html"},{"id":"MEJE-KW-002903","row_version":2,"title":"연인을 얻으려 성적 이미지로 바뀌기","original":"Be a Whore to Get Your Man","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"상대의 관심을 얻으려고 옷차림과 태도를 갑자기 성적으로 바꾼다. 원하는 변화인지 주변의 압력인지에 따라 인물의 선택권이 달라진다. 겉모습을 바꾸는 꾸밈을 바꾸자 뒤늦게 아름답다고 알아보기에 연애의 압력이 더해진 경우다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002903/index.html"},{"id":"MEJE-KW-002904","row_version":1,"title":"자신이 지켜 온 가치의 반대편에 서기","original":"Became Their Own Antithesis","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"오래 믿던 신념과 정반대의 행동을 하는 인물로 변한다. 무엇이 변화를 낳았는지 보여 주어 단순한 반전 이상의 성장을 만든다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002904/index.html"},{"id":"MEJE-KW-002905","row_version":2,"title":"무심코 한 말이 약속이 되기","original":"Be Careful What You Say","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"가볍게 내뱉은 말이 마법이나 사회 규칙 때문에 지켜야 할 약속으로 바뀐다. 발화의 의도와 실제 효력의 차이가 사건을 낳는다. 말이 곧 결과가 되는 소원이 예상 밖의 방식으로 이루어지기와 약속의 효력을 비교할 수 있다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002905/index.html"},{"id":"MEJE-KW-002906","row_version":2,"title":"소원이 예상 밖의 방식으로 이루어지기","original":"Be Careful What You Wish For","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"바라던 일이 실제로 일어나지만 빠뜨린 조건 때문에 다른 손실이 따른다. 소원의 문장과 그 뒤의 책임을 함께 다룬다. 무심한 말에 책임이 따르는 무심코 한 말이 약속이 되기와 소원의 문장을 함께 본다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002906/index.html"},{"id":"MEJE-KW-002907","row_version":2,"title":"운명이라는 말에 스스로 복종하기","original":"Because Destiny Says So","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"미래가 정해졌다고 믿는 인물이 그 예언을 이루는 방향으로 행동한다. 가능성의 예고가 인물 자신의 선택을 묶는 과정이다. 예언을 듣고 이를 따르는 선택에도 무심코 한 말이 약속이 되기의 말의 힘이 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002907/index.html"},{"id":"MEJE-KW-002908","row_version":2,"title":"잘한다는 이유로 해로운 일을 계속하기","original":"Because I'm Good At It","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 문제 있는 일을 그만둘 기회가 생겨도 능숙함에서 얻는 만족 때문에 남는다. 기술에 대한 자부심과 행동의 책임이 충돌한다. 자신의 능력을 다른 삶으로 옮기면 자신이 지켜 온 가치의 반대편에 서기의 변화가 시작될 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002908/index.html"},{"id":"MEJE-KW-002909","row_version":2,"title":"부모라는 이유만으로 명령하기","original":"Because I Said So","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"부모가 이유를 설명하지 않고 자신의 지위만 내세워 아이의 행동을 막는다. 보호하려는 의도와 설명을 요구하는 아이의 마음이 어긋날 수 있다. 설명 없이 내린 결정이 잘 버틴다는 이유로 돌봄에서 밀리기의 돌봄 격차로 이어질 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002909/index.html"},{"id":"MEJE-KW-002910","row_version":2,"title":"잘 버틴다는 이유로 돌봄에서 밀리기","original":"Because You Can Cope","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"보호자가 더 약해 보이는 다른 사람에게 힘을 쏟으며 자립적인 인물은 혼자 감당하리라 여긴다. 능력이 있다는 평가가 필요한 도움을 가리는 관계다. 부모의 명령을 앞세운 부모라는 이유만으로 명령하기에서도 아이의 필요가 가려질 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002910/index.html"},{"id":"MEJE-KW-002911","row_version":2,"title":"작은 친절을 오래 기억하며 돕기","original":"Because You Were Nice to Me","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"무시받던 인물이 한 번의 진심 어린 호의를 잊지 않고 어려운 순간 그 사람을 돕는다. 보답의 크기보다 처음 존중받았던 경험이 행동을 이끈다. 어려운 시기에 내민 손이 괴롭힘을 당하는 사람의 친구가 되기의 시작이 될 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002911/index.html"},{"id":"MEJE-KW-002912","row_version":2,"title":"인간이 아닌 존재가 인간이 되기","original":"Become a Real Boy","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인형이나 기계, 저주받은 존재가 인간의 몸과 사회적 자리를 얻는다. 변화가 소원인지 강제인지에 따라 새 몸의 의미가 달라진다. 인간의 몸을 얻은 뒤에도 변한 몸을 받아들이기 어려워하기의 갈등이 남을 수 있다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002912/index.html"},{"id":"MEJE-KW-002913","row_version":2,"title":"자신의 무기와 합쳐져 변신하기","original":"Become Your Weapon","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 쓰던 무기와 몸을 하나로 합쳐 새로운 전투 형태를 얻는다. 무기의 능력뿐 아니라 손과 몸의 쓰임이 어떻게 달라지는지가 중요하다. 겉모습이 바뀌는 입은 복장 그대로 변신하기와 달리 무기가 변화의 중심이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002913/index.html"},{"id":"MEJE-KW-002914","row_version":2,"title":"그림 속 인물처럼 보이게 끼어들기","original":"Becoming Part of the Image","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 포스터나 그림 앞에 서서 자기 얼굴이나 몸이 이미지의 일부처럼 보이게 한다. 평면과 실제 공간이 잠깐 겹쳐 생기는 시각적 농담이다. 그림의 경계를 이용하는 농담은 카메라 밖이면 인물도 못 보는 것처럼 행동하기의 화면 착각과 닿는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002914/index.html"},{"id":"MEJE-KW-002915","row_version":2,"title":"거짓 허풍을 실제 능력으로 만들기","original":"Becoming the Boast","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"한때 해냈다고 부풀린 일을 언젠가 정말 해내야 하는 상황에 놓인다. 들통날 두려움이 배우고 행동할 동기가 된다. 자기 말이 사실이라고 믿는 자기 거짓말을 사실로 믿기와는 말 이후의 행동이 다르다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002915/index.html"},{"id":"MEJE-KW-002916","row_version":2,"title":"입은 복장 그대로 변신하기","original":"Becoming the Costume","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"가면이나 옷으로 흉내 낸 대상이 실제 몸과 능력이 된다. 축제의 놀이가 세계의 규칙을 바꾸는 사건으로 커진다. 변한 모습이 오래 남으면 가짜 신분이 진짜 삶이 되기처럼 정체성을 바꿀 수 있다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002916/index.html"},{"id":"MEJE-KW-002917","row_version":2,"title":"소원 때문에 정령이 되기","original":"Becoming the Genie","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"더 큰 힘을 바라던 인물이 소원을 들어주는 존재 자체로 변한다. 능력의 획득과 함께 새로운 제약까지 받아들이게 된다. 새로운 존재가 된다는 점에서 인간이 아닌 존재가 인간이 되기와 소원의 방향이 다르다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002917/index.html"},{"id":"MEJE-KW-002918","row_version":2,"title":"가짜 신분이 진짜 삶이 되기","original":"Becoming the Mask","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"잠입이나 위장을 위해 만든 인격에 익숙해져 원래 이름보다 그 모습으로 살고 싶어진다. 임무의 성공과 자기 정체성의 선택이 충돌한다. 마법 없이도 입은 복장 그대로 변신하기처럼 외형과 역할이 삶을 바꿀 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002918/index.html"},{"id":"MEJE-KW-002919","row_version":2,"title":"여러 동반자를 권력의 장식으로 보이기","original":"Bed Full of Women","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"권력자가 자신 곁에 잠든 여러 사람을 보여 줘 성적 매력과 지위를 과시한다. 주변 인물을 독립된 사람보다 소유의 표지로 쓰는 시선을 살핀다. 인물을 장식으로 보는 시선은 이국적 무희 의상으로 지역을 단순화하기의 복식 이미지와 연결된다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002919/index.html"},{"id":"MEJE-KW-002920","row_version":1,"title":"헝클어진 머리로 아픔을 알리기","original":"Bedhead-itis","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"평소 머리를 정돈하던 인물이 몸이 좋지 않은 날 흐트러진 모습으로 나타난다. 머리 상태는 장면의 시각적 신호이지 질병을 판단하는 기준은 아니다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002920/index.html"},{"id":"MEJE-KW-002921","row_version":2,"title":"이국적 무희 의상으로 지역을 단순화하기","original":"Bedlah Babe","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"배를 드러내는 공연 복식을 특정 지역 전체의 일상복처럼 그린다. 춤의 무대 의상과 다양한 지역 사람들의 실제 생활을 구분해 본다. 복식의 이국성을 앞세워 인물을 장식처럼 쓰는 여러 동반자를 권력의 장식으로 보이기와 겹친다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002921/index.html"},{"id":"MEJE-KW-002922","row_version":1,"title":"정신의료 시설을 음산한 감옥처럼 그리기","original":"Bedlam House","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"도움이 필요한 사람이 들어간 시설을 어둡고 폭력적인 곳으로 꾸며 공포의 무대로 만든다. 실제 정신건강 돌봄을 이런 이미지 하나로 단정하지 않는다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-002922/index.html"},{"id":"MEJE-KW-002923","row_version":2,"title":"옆에 누운 사람을 뒤늦게 보여 주기","original":"Bedmate Reveal","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"잠에서 깬 인물만 먼저 비춘 뒤 화면을 옮겨 같은 침대의 다른 사람을 드러낸다. 관객이 관계를 추측하는 순서를 카메라가 조절한다. 곁에 있는 사람이 비밀 관계의 상대라면 집 안에서 불륜을 들키기로 이어진다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-002923/index.html"},{"id":"MEJE-KW-002924","row_version":1,"title":"사막에서 이동 중인 사람들에게 구조받기","original":"Bedouin Rescue Service","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"물과 길을 잃은 여행자가 지나가던 무리에게 발견돼 살아난다. 구조자를 특정 민족의 당연한 역할로 쓰지 않고 그들의 선택과 사정을 함께 볼 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002924/index.html"},{"id":"MEJE-KW-002925","row_version":2,"title":"집 안에서 불륜을 들키기","original":"Bedroom Adultery Scene","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"비밀 관계의 두 사람이 집에 있다가 예상보다 일찍 돌아온 동거인과 마주친다. 들키지 않으려는 소동이나 관계의 파열로 전개된다. 두 사람을 차례로 보여 주는 옆에 누운 사람을 뒤늦게 보여 주기가 비밀을 드러내는 방식이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002925/index.html"},{"id":"MEJE-KW-002926","row_version":1,"title":"침실에서 만든 듯한 친밀한 팝","original":"Bedroom Pop","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"가까운 목소리와 간결한 편곡으로 개인의 일기 같은 정서를 전하는 대중음악의 흐름. 실제 녹음 장소보다 청자에게 들리는 거리감이 분류의 핵심이다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-002926/index.html"},{"id":"MEJE-KW-002927","row_version":1,"title":"흰 천을 뒤집어쓴 유령","original":"Bedsheet Ghost","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"형체가 보이지 않는 영을 흰 천의 윤곽과 두 눈 구멍으로 그린다. 장례의 천에서 온 이미지가 익숙한 유령 실루엣으로 굳어진 것이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002927/index.html"},{"id":"MEJE-KW-002928","row_version":1,"title":"침대 시트로 탈출 줄 만들기","original":"Bedsheet Ladder","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"방에 갇힌 인물이 시트를 이어 창밖으로 내려갈 길을 만든다. 천의 길이와 결속력은 작품이 정한 탈출의 설득력을 좌우한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002928/index.html"},{"id":"MEJE-KW-002929","row_version":2,"title":"잠든 사람에게 말을 걸어 생각을 유도하기","original":"Bedtime Brainwashing","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"다른 사람이 잠든 동안 말을 반복해 꿈이나 다음 행동에 영향을 주려 한다. 실제 효과가 있는 능력인지 인물의 믿음인지는 작품의 규칙에 달려 있다. 반복된 말을 통해 행동을 유도하는 반복된 자극으로 행동을 길들이기와 닿는다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002929/index.html"},{"id":"MEJE-KW-002930","row_version":2,"title":"상대를 속여 친밀한 관계를 맺기","original":"Bed Trick","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"다른 사람인 척하며 상대가 오인한 상태에서 성적 관계를 맺는다. 신분을 속인 행위는 동의의 조건을 훼손하므로 로맨스 장난이 아닌 침해로 살핀다. 단순한 옆에 누운 사람을 뒤늦게 보여 주기와 달리 신분을 속여 동의 조건을 훼손한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002930/index.html"},{"id":"MEJE-KW-002931","row_version":2,"title":"벌떼를 공포의 무리로 그리기","original":"Bee Afraid","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"벌이 한꺼번에 날아와 인물을 쫓는 위협으로 등장한다. 실제 벌의 생태와 작품이 키운 공격 이미지를 구분한다. 공포의 무리를 공격자가 조종하면 벌을 무기로 내보내기가 된다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-002931/index.html"},{"id":"MEJE-KW-002932","row_version":2,"title":"벌을 무기로 내보내기","original":"Bee-Bee Gun","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"곤충 무리를 담은 장치나 능력을 사용해 상대를 위협한다. 날아다니는 작은 존재가 공격자의 통제 아래 있는지가 전투의 규칙이다. 벌을 위협으로 보는 벌떼를 공포의 무리로 그리기가 무기의 인상을 키운다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002932/index.html"},{"id":"MEJE-KW-002933","row_version":2,"title":"상처에 고기를 대는 낡은 치료 장면","original":"Beef Bandage","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"멍든 얼굴에 고기 조각을 올리는 오래된 화면 관습. 실제 상처 처치의 안내가 아니며 인물이 믿는 민간요법으로 구분한다. 싸움 뒤 상처를 알아차리는 위기가 지난 뒤에야 상처를 알아차리기에서 등장할 수 있는 낡은 화면 관습이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002933/index.html"},{"id":"MEJE-KW-002934","row_version":2,"title":"강한 적으로 너무 이른 진입 막기","original":"Beef Gate","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"자유롭게 이동할 수 있는 게임에서 초반 지역 밖에 압도적인 적을 배치한다. 보이지 않는 벽 대신 전투의 위험으로 진행 순서를 알린다. 초반의 강한 적에게 결전기를 처음부터 사용하기를 써도 통할지 시험하게 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002934/index.html"},{"id":"MEJE-KW-002935","row_version":1,"title":"육각 무늬가 이어진 보호막","original":"Beehive Barrier","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"작은 기하학 조각들이 연결돼 인물이나 기계를 덮는 장벽을 만든다. 맞은 부분만 반응하는 화면이 막의 구조와 힘을 보여 준다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002935/index.html"},{"id":"MEJE-KW-002936","row_version":1,"title":"높이 쌓아 올린 벌집머리","original":"Beehive Hairdo","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"머리카락을 위로 크게 부풀려 벌집 같은 윤곽을 만든다. 특정 시대의 분위기나 인물의 꾸밈 방식을 빠르게 알리는 복식 신호다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002936/index.html"},{"id":"MEJE-KW-002937","row_version":1,"title":"파리의 군주로 그리는 악마","original":"Beelzebub","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"벨제부브라는 이름의 존재를 곤충과 부패, 지옥의 권력에 연결해 표현한다. 종교 전통의 해석과 작품마다 달라지는 괴물 이미지를 구분한다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-002937/index.html"},{"id":"MEJE-KW-002938","row_version":2,"title":"허구 인물이 역사 사건의 배후에 있기","original":"Been There, Shaped History","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"실제로 기록된 사건에 작품 속 인물이 몰래 관여했다고 설정한다. 알려진 역사와 이야기 안의 숨은 원인이 겹쳐 대체 역사의 맛을 만든다. 역사 속 인물을 유명 역사 인물에게 비밀 정체를 주기로 바꾸는 이야기도 같은 재구성이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-002938/index.html"},{"id":"MEJE-KW-002939","row_version":2,"title":"벌의 특징을 가진 사람들","original":"Bee People","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"날개와 더듬이 같은 몸의 특징, 집단 생활의 규칙을 지닌 인간형 종족. 실제 벌의 생태를 그대로 사회 제도로 옮기지 않고 세계 안의 선택을 설정한다. 벌의 몸을 가진 인물이 벌을 무기로 내보내기의 주체가 될 수 있다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-002939/index.html"},{"id":"MEJE-KW-002940","row_version":1,"title":"컴퓨터가 작업할 때마다 삑 소리 내기","original":"Beeping Computers","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"화면의 계산이나 확대 동작마다 기계가 신호음을 낸다. 소리가 보이지 않는 처리를 관객이 알아차리도록 돕는 연출이다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-002940/index.html"},{"id":"MEJE-KW-002941","row_version":2,"title":"맥주 한 모금에 과장되게 감탄하기","original":"Beergasm","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"인물이 음료를 마신 뒤 큰 숨소리와 외침으로 만족을 표현한다. 맛의 경험을 즉시 전하는 몸짓이며 음주 효과의 사실적 설명은 아니다. 즐거운 음주 장면과 술에 취해 타인의 매력을 달리 평가하기의 평가 변화는 다른 효과다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-002941/index.html"},{"id":"MEJE-KW-002942","row_version":2,"title":"술에 취해 타인의 매력을 달리 평가하기","original":"Beer Goggles","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"음주한 인물이 평소와 다른 외모 판단을 내리고 나중에 이를 이야기한다. 상대의 가치를 점수화하는 시선과 취한 사람의 행동을 함께 살핀다. 취한 사람의 판단과 맥주 한 모금에 과장되게 감탄하기의 과장된 만족을 구분한다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002942/index.html"},{"id":"MEJE-KW-002943","row_version":2,"title":"유명 역사 인물에게 비밀 정체를 주기","original":"Beethoven Was an Alien Spy","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"실제 기록에 남은 인물이 외계인이나 마법사였다는 식으로 숨은 삶을 덧붙인다. 알려진 업적과 허구의 비밀을 장난스럽게 다시 연결한다. 비밀 정체가 허구 인물이 역사 사건의 배후에 있기의 원인이 되는 설정도 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-002943/index.html"},{"id":"MEJE-KW-002944","row_version":1,"title":"딱정벌레에 몰두하는 인물","original":"Beetle Maniac","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"딱정벌레의 모양과 움직임을 오래 관찰하고 수집하는 취미를 지닌 인물. 주변이 이해하지 못하는 작은 관심이 독자적인 삶의 중심이 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002944/index.html"},{"id":"MEJE-KW-002945","row_version":1,"title":"변화 전후 사진으로 효과를 주장하기","original":"\"Before\" and \"After\" Pictures","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"두 시기의 사진을 나란히 놓아 제품이나 행동의 성과를 보여 주려 한다. 촬영 조건과 선택한 장면이 비교의 인상을 바꿀 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-002945/index.html"},{"id":"MEJE-KW-002946","row_version":2,"title":"마음이 바뀌기 전에 떠나라고 놓아주기","original":"Before I Change My Mind","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"상대를 붙잡고도 잠시 생각을 바꿔 도망칠 틈을 준다. 용서나 계산, 망설임 중 무엇이 결정의 이유인지 관계에 남는다. 상대를 놓아준 결정이 적과 이야기를 나눠 친구가 되기의 시작인지 작품이 정한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002946/index.html"},{"id":"MEJE-KW-002947","row_version":2,"title":"자기 출생 이전의 문화를 모른다며 지나치기","original":"Before My Time","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"예전 작품이나 사건을 들은 인물이 자기 시대보다 앞섰다는 이유만으로 알아볼 수 없다고 한다. 세대의 차이를 드러내는 말이지만 실제 지식의 경계를 단정하지 않는다. 오래된 문화를 모른다는 말은 어둠이 오기 전의 번영을 기억하기의 기억도 읽지 못하게 한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002947/index.html"},{"id":"MEJE-KW-002948","row_version":2,"title":"어둠이 오기 전의 번영을 기억하기","original":"Before the Dark Times","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"지금은 무너진 나라가 한때 풍요롭고 평화로웠다는 기억을 남긴다. 그 시절을 되찾으려는 집단마다 무엇을 복원할지 다르게 그릴 수 있다. 잃어버린 시대를 되찾는 이야기는 속편에서 늦게 밝혀진 행복한 결말로 끝날 수도 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-002948/index.html"},{"id":"MEJE-KW-002949","row_version":2,"title":"괴롭힘을 당하는 사람의 친구가 되기","original":"Befriending the Bullied","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"따돌림이나 괴롭힘을 겪는 인물에게 다른 사람이 다가가 곁을 지킨다. 우정이 피해를 모두 해결한다는 단순한 결말보다 함께 선택할 수 있는 행동을 보여 준다. 작은 호의를 기억하는 작은 친절을 오래 기억하며 돕기와 관계의 시작을 공유한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002949/index.html"},{"id":"MEJE-KW-002950","row_version":2,"title":"적과 이야기를 나눠 친구가 되기","original":"Befriending the Enemy","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"서로 맞서던 인물들이 이유를 묻고 시간을 보내며 관계를 바꾼다. 갈등의 조건이 무엇이었는지 알수록 화해의 의미가 선명해진다. 적을 놓아주는 마음이 바뀌기 전에 떠나라고 놓아주기 다음에 대화를 시작할 수도 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002950/index.html"},{"id":"MEJE-KW-002951","row_version":1,"title":"도움이 필요하다는 팻말을 든 사람","original":"Beggar with a Signboard","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"거리의 인물이 자신의 형편과 요청을 적은 팻말을 들고 선다. 글씨만으로 그 사람의 삶 전체를 판단하지 않고 누가 읽고 반응하는지 본다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-002951/index.html"},{"id":"MEJE-KW-002952","row_version":1,"title":"처음 해 본 일이 뜻밖에 잘되기","original":"Beginner's Luck","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"경험이 거의 없는 인물이 숙련자도 어려워하는 일을 한 번에 성공한다. 우연한 행운과 이후의 실제 능력은 구분된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002952/index.html"},{"id":"MEJE-KW-002953","row_version":2,"title":"결전기를 처음부터 사용하기","original":"Begin with a Finisher","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"싸움의 마지막에 쓸 법한 강한 기술을 시작하자마자 꺼낸다. 힘을 아끼는 통상적 전개를 거꾸로 해 상대와 관객의 예상을 흔든다. 강한 적으로 너무 이른 진입 막기으로 막힌 길을 강한 기술로 시험할 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002953/index.html"},{"id":"MEJE-KW-002954","row_version":1,"title":"귀찮은 사람에게 떠나 달라고 돈 주기","original":"\"Begone\" Bribe","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"소란을 멈추고 싶어 상대에게 작은 보상을 건네며 사라져 달라고 한다. 요구를 받아주는 행동이 오히려 다음 소란의 유인이 될 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002954/index.html"},{"id":"MEJE-KW-002955","row_version":2,"title":"괴롭히던 사람에게 도움을 구하기","original":"Beg the Dog","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"평소 힘을 남용하던 인물이 궁지에 몰리자 피해자에게 구해 달라고 빈다. 용서를 청하는 말과 과거 행동을 책임지는 일은 다르다. 도움을 구하는 일이 바로 적과 이야기를 나눠 친구가 되기를 뜻하지는 않는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002955/index.html"},{"id":"MEJE-KW-002956","row_version":2,"title":"반복된 자극으로 행동을 길들이기","original":"Behavioral Conditioning","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"특정 신호가 울릴 때마다 같은 행동을 하도록 인물이 습관을 배우거나 강요받는다. 누가 훈련을 설계했는지와 선택권이 남아 있는지를 살핀다. 잠든 사람에게 말을 반복하는 잠든 사람에게 말을 걸어 생각을 유도하기도 행동을 유도하려는 시도다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002956/index.html"},{"id":"MEJE-KW-002957","row_version":2,"title":"몸보다 먼저 행동이 변하기","original":"Behavioral Transformation First","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"저주나 변신이 겉모습에 나타나기 전에 식성과 버릇, 충동이 먼저 달라진다. 인물이 아직 이전 몸인 상태에서 변화를 알아차리게 한다. 겉모습이 바뀌기 전의 혼란이 변한 몸을 받아들이기 어려워하기로 이어진다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002957/index.html"},{"id":"MEJE-KW-002958","row_version":1,"title":"거대 생물 둘이 맞붙기","original":"Behemoth Battle","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"보통 전투보다 훨씬 큰 두 존재가 도시나 들판에서 싸운다. 움직임의 규모가 주변 사람의 피난과 공간의 파괴를 함께 불러온다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002958/index.html"},{"id":"MEJE-KW-002959","row_version":2,"title":"가느다란 물건 뒤에 온몸 숨기기","original":"Behind a Stick","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"몸보다 좁은 기둥이나 나무 뒤에 인물이 완전히 가려진 듯 행동한다. 보이는 크기의 어긋남을 화면의 농담으로 쓴다. 카메라의 경계를 이용한다는 점에서 카메라 밖이면 인물도 못 보는 것처럼 행동하기와 닮는다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-002959/index.html"},{"id":"MEJE-KW-002960","row_version":2,"title":"성공 뒤에 가려진 조력자","original":"Behind Every Great Man","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 인물만 칭찬받는 성취에 다른 사람의 노동과 판단이 깊이 들어 있다. 특히 가족 안의 보이지 않는 기여가 누구의 이름으로 기록되는지 살핀다. 조직에서는 상사의 뒤처리를 떠맡는 보조자의 보이지 않는 노동으로 나타날 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002960/index.html"},{"id":"MEJE-KW-002961","row_version":2,"title":"카메라 밖이면 인물도 못 보는 것처럼 행동하기","original":"Behind the Black","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"화면 밖에 있는 물건이 등장인물의 시야에는 들어올 텐데도 없는 것처럼 취급된다. 카메라의 경계와 이야기 세계의 공간을 혼동한 연출이다. 가느다란 물건 뒤에 온몸 숨기기처럼 화면이 보여 주는 범위를 공간 전체로 오인한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-002961/index.html"},{"id":"MEJE-KW-002962","row_version":1,"title":"짧고 담백한 문장으로 쓰기","original":"Beige Prose","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"수식과 비유를 줄이고 간단한 말과 문장으로 정보를 전한다. 속도와 명료함이 살아나는 만큼 필요한 감정이나 맥락이 빠지지 않게 한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002962/index.html"},{"id":"MEJE-KW-002963","row_version":2,"title":"악행을 택한 뒤 대가를 겪기","original":"Being Evil Sucks","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"해를 끼치는 길이 쉬워 보였던 인물이 관계와 신뢰를 잃으며 선택의 비용을 마주한다. 악역의 힘과 그 삶의 만족을 같은 것으로 보지 않는다. 올바른 선택의 비용을 다루는 옳은 일을 해도 손해를 감수하기와 다른 길의 대가를 본다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002963/index.html"},{"id":"MEJE-KW-002964","row_version":2,"title":"신의 힘을 가진 뒤 책임에 지치기","original":"Being God Is Hard","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"세계에 영향을 미치는 능력을 얻은 인물이 끝없는 요청과 결과의 책임을 감당한다. 전능해 보이는 위치에도 결정의 무게가 남는다. 힘이 클수록 옳은 일을 해도 손해를 감수하기의 선택이 더 많은 사람에게 닿는다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002964/index.html"},{"id":"MEJE-KW-002965","row_version":2,"title":"옳은 일을 해도 손해를 감수하기","original":"Being Good Sucks","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 바른 선택을 하고도 시간과 관계, 안전을 잃는다. 보상 없이도 그 행동을 계속할지에서 신념의 힘이 드러난다. 악행의 대가를 겪는 악행을 택한 뒤 대가를 겪기와 선행의 부담을 나란히 본다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002965/index.html"},{"id":"MEJE-KW-002966","row_version":2,"title":"인간의 몸과 한계를 답답해하기","original":"Being Human Sucks","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"다른 형태의 삶을 경험한 인물이 인간의 감각과 수명을 좁게 느낀다. 인간이 되는 일이 모두에게 같은 소원은 아니라는 관점이다. 모든 존재가 인간이 아닌 존재가 인간이 되기를 소망하는 것은 아니라는 관점이다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002966/index.html"},{"id":"MEJE-KW-002967","row_version":1,"title":"사적인 감정을 직업 밖에 두려는 인물","original":"Being Personal Isn't Professional","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"일터의 관계에서 감정을 드러내지 않고 역할과 절차만 따르려 한다. 전문성을 지키려는 의도와 사람을 멀리하는 결과가 어긋날 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002967/index.html"},{"id":"MEJE-KW-002968","row_version":1,"title":"자기 몸을 붓으로 쓰기","original":"Being the Brush","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"붓 대신 몸에 물감을 묻혀 캔버스나 벽에 흔적을 남긴다. 움직임 자체가 그림의 형태와 제작 과정에 남는다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-002968/index.html"},{"id":"MEJE-KW-002969","row_version":2,"title":"고통을 겪자 악해졌다고 단정하기","original":"Being Tortured Makes You Evil","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"폭력을 겪은 인물이 곧바로 잔혹한 사람이 된다고 이야기가 설명한다. 피해 경험을 도덕적 결함의 원인처럼 단정하는 재현 관습을 비판적으로 살핀다. 고통을 겪은 뒤의 선택과 악행을 택한 뒤 대가를 겪기의 책임을 같은 것으로 단정하지 않는다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002969/index.html"},{"id":"MEJE-KW-002970","row_version":1,"title":"큰 꿈이 없다는 이유로 사람을 낮춰 보기","original":"Being Unambitious Is Bad","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 조용히 살고 싶다고 말하면 주변이 의욕 없는 삶으로 평가한다. 성공의 한 기준을 모두에게 강요하는 이야기의 가치관을 드러낸다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002970/index.html"},{"id":"MEJE-KW-002971","row_version":1,"title":"보이지 않는 시선을 알아차리기","original":"Being Watched","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 주변에 아무도 없어도 누군가 자신을 지켜본다는 느낌이나 단서를 얻는다. 실제 감시와 불안의 표현 중 어느 쪽인지는 장면의 증거로 정한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002971/index.html"},{"id":"MEJE-KW-002972","row_version":2,"title":"벨라루스 미디어","original":"Belarusian Media","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"벨라루스에서 만들어졌거나 그 창작 문화와 이어지는 영상, 음악, 문학, 게임 등을 탐색하는 지역별 미디어 분류. 개별 작품은 확인된 뒤 독립 카드로 연결한다. 다른 지역의 상위 분류로 벨기에 미디어도 있다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-002972/index.html"},{"id":"MEJE-KW-002973","row_version":1,"title":"늦게야 엄격한 훈육을 받기","original":"Belated Child Discipline","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"오랫동안 행동의 결과를 피하던 인물이 뒤늦게 제지와 책임을 마주한다. 처벌의 통쾌함보다 무엇을 배워야 하는지에 주목한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002973/index.html"},{"id":"MEJE-KW-002974","row_version":2,"title":"속편에서 늦게 밝혀진 행복한 결말","original":"Belated Happy Ending","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"앞 작품이 모호하게 남긴 인물의 운명을 오랜 뒤 나온 다음 작품이 긍정적으로 정한다. 열린 결말을 보던 관객의 해석도 새 정보와 만난다. 무너진 옛 세계를 다룬 어둠이 오기 전의 번영을 기억하기에도 뒤늦은 결말이 붙을 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-002974/index.html"},{"id":"MEJE-KW-002975","row_version":2,"title":"위기가 지난 뒤에야 상처를 알아차리기","original":"Belated Injury Realization","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"싸움이나 탈출이 끝난 뒤 인물이 몸의 손상을 발견한다. 긴장한 장면과 회복 장면의 감각 차이를 보여 주는 연출이며 상처의 안전성을 뜻하지 않는다. 뒤늦게 상처를 발견한 장면에서 상처에 고기를 대는 낡은 치료 장면가 등장해도 치료법은 아니다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002975/index.html"},{"id":"MEJE-KW-002976","row_version":2,"title":"떠난 뒤에야 사랑을 깨닫기","original":"Belated Love Epiphany","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"곁에 있던 사람이 사라진 뒤 빈자리를 느끼며 자신의 감정을 새로 이해한다. 부재가 관계의 이름을 뒤늦게 바꾸는 전개다. 말다툼 속 감정을 숨긴 다투면서 끌리는 두 인물가 부재 뒤에 드러날 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002976/index.html"},{"id":"MEJE-KW-002977","row_version":2,"title":"상사의 뒤처리를 떠맡는 보조자","original":"Beleaguered Assistant","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"보조자가 상사의 실수와 무리한 요구를 수습하며 조직을 실제로 굴린다. 공로와 권한이 다른 사람에게 나뉜 관계다. 위에 있는 사람도 부하들 때문에 지친 상사처럼 조직의 부담을 겪을 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002977/index.html"},{"id":"MEJE-KW-002978","row_version":2,"title":"끝없는 비용을 감당하는 후원자","original":"Beleaguered Benefactor","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"팀의 활동을 돕던 인물이 예상보다 큰 지출과 손실을 반복해 떠안는다. 넉넉한 자원도 무한하지 않다는 설정이 계획을 바꾼다. 상사의 뒤처리를 떠맡는 보조자의 노동과 후원자의 지출은 서로 다른 숨은 비용이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002978/index.html"},{"id":"MEJE-KW-002979","row_version":2,"title":"부하들 때문에 지친 상사","original":"Beleaguered Boss","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"책임자가 부하들의 실수와 다툼을 해결하느라 본래의 계획을 펼치지 못한다. 권력을 쥐었다는 이미지와 실제 관리 노동의 차이가 드러난다. 상사와 상사의 뒤처리를 떠맡는 보조자가 서로 다른 이유로 지칠 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002979/index.html"},{"id":"MEJE-KW-002980","row_version":2,"title":"밀린 일에 둘러싸인 친절한 행정가","original":"Beleaguered Bureaucrat","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"도움을 주려는 담당자가 겹친 요청과 절차 속에서 한 사람에게 시간을 충분히 쓰지 못한다. 제도의 한계와 개인의 태도를 구분하는 인물형이다. 조직을 관리한다는 점에서 부하들 때문에 지친 상사와 닮지만 권한의 범위는 다르다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002980/index.html"},{"id":"MEJE-KW-002981","row_version":2,"title":"곤경에 빠진 옛 친구를 돕기","original":"Beleaguered Childhood Friend","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"어릴 적 알던 사람이 큰 문제를 안고 돌아오자 주인공이 지난 친분을 믿고 돕는다. 추억과 지금의 사실이 충돌할 수 있다. 오래된 친분을 다시 확인하는 일은 적과 이야기를 나눠 친구가 되기와 관계의 출발점이 다르다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002981/index.html"},{"id":"MEJE-KW-002982","row_version":2,"title":"벨기에 만화","original":"Belgian Comics","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"벨기에에서 만들어진 만화와 그 출판·연재 문화를 탐색하는 지역별 미디어 분류. 개별 작품과 창작자는 확인한 뒤 각각 독립 카드로 연결한다. 벨기에 미디어 안에서 만화를 따로 살피는 하위 탐색 분류다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-002982/index.html"},{"id":"MEJE-KW-002983","row_version":2,"title":"벨기에 영화","original":"Belgian Films","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"벨기에 제작 또는 공동제작과 연결되는 영화를 탐색하는 지역별 미디어 분류. 국적을 하나로 단정하기 어려운 작품은 제작 관계를 따로 기록한다. 벨기에 미디어 안에서 영화를 따로 살피는 하위 탐색 분류다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-002983/index.html"},{"id":"MEJE-KW-002984","row_version":2,"title":"벨기에 미디어","original":"Belgian Media","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"벨기에의 만화, 영화, 방송, 음악 등 여러 형식의 창작물을 묶어 탐색하는 지역별 미디어 분류. 하위 분야와 작품 카드는 확인한 범위에서 연결한다. 방송 형식은 벨기에 방송 시리즈에서 더 세분해 찾을 수 있다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-002984/index.html"},{"id":"MEJE-KW-002985","row_version":2,"title":"벨기에 방송 시리즈","original":"Belgian Series","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"벨기에에서 제작되거나 제작에 참여한 텔레비전·애니메이션 시리즈를 탐색하는 지역별 미디어 분류. 공동제작 관계는 작품별로 구분한다. 벨기에 미디어의 방송 분야를 따로 모으는 분류다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-002985/index.html"},{"id":"MEJE-KW-002986","row_version":1,"title":"믿음을 어리석음의 증거로 그리기","original":"Belief Makes You Stupid","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"종교적 신념을 가진 인물이 현실을 전혀 보지 못하는 사람으로만 묘사된다. 믿음의 내용과 인물의 판단력을 자동으로 묶는 고정관념을 살핀다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002986/index.html"},{"id":"MEJE-KW-002987","row_version":2,"title":"믿는 대상을 위해 증거를 꾸미기","original":"Believer Fakes Evidence","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"실제로 있을지 모르는 존재를 믿는 인물이 남을 설득하려 가짜 흔적을 만든다. 신념과 증거의 정직성을 별개로 보게 되는 사건이다. 남을 설득하려 만든 흔적을 오래 믿으면 자기 거짓말을 사실로 믿기와 연결된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002987/index.html"},{"id":"MEJE-KW-002988","row_version":2,"title":"자기 거짓말을 사실로 믿기","original":"Believing Their Own Lies","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"오랫동안 반복한 주장에 인물 자신도 의심을 멈춘다. 남을 속이던 말이 자기 기억을 다시 만드는 과정이다. 처음에는 의도적인 믿는 대상을 위해 증거를 꾸미기였을 수도 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002988/index.html"},{"id":"MEJE-KW-002989","row_version":1,"title":"팔다리 끝이 크게 벌어진 로봇","original":"Bell-Bottom-Limbed Bots","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"로봇의 팔뚝과 종아리를 어깨나 허벅지보다 크게 만들어 독특한 실루엣을 만든다. 장갑과 추진 장치의 위치가 외형의 이유가 될 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002989/index.html"},{"id":"MEJE-KW-002990","row_version":2,"title":"다투면서 끌리는 두 인물","original":"Belligerent Sexual Tension","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"서로 날카롭게 말하는 두 사람이 동시에 가까워지고 싶은 마음을 숨긴다. 말다툼이 호감의 표현인지 실제 갈등인지 관계 속에서 드러나야 한다. 다툼 속 호감을 알아차리는 순간이 떠난 뒤에야 사랑을 깨닫기로 늦어질 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002990/index.html"},{"id":"MEJE-KW-002991","row_version":2,"title":"설정의 빈틈을 이야기의 흐름으로 넘기기","original":"Bellisario's Maxim","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"세부 규칙에 모든 시간을 쓰기보다 인물의 선택과 사건의 감정에 집중하도록 관객을 이끈다. 작품이 세운 핵심 규칙까지 무시하지는 않는 연출 선택이다. 이야기에서 허용한 생략과 카메라 밖이면 인물도 못 보는 것처럼 행동하기의 공간 오류는 구분한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-002991/index.html"},{"id":"MEJE-KW-002992","row_version":1,"title":"큰 몸으로 상대를 덮쳐 공격하기","original":"Belly Flop Crushing","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"몸집이 큰 인물이 몸을 띄워 상대 위로 내려앉는다. 크기를 공격의 규모로 보여 주되 체형 자체를 우스움이나 악의의 증거로 만들지 않는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002992/index.html"},{"id":"MEJE-KW-002993","row_version":2,"title":"배에 또 하나의 입이 있기","original":"Belly Mouth","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이나 괴물의 배 부분에 별도의 입이 열려 먹거나 말한다. 몸의 통상적인 구조가 바뀌어 그 존재의 위험과 능력을 드러낸다. 배에 난 입으로 플레이어를 삼키면 보스의 몸속에서 싸우기가 될 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002993/index.html"},{"id":"MEJE-KW-002994","row_version":2,"title":"보스의 몸속에서 싸우기","original":"Belly of the Boss","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"적에게 삼켜진 플레이어가 내부 공간을 이동하며 약점을 찾는다. 보스의 몸이 잠시 미로와 전투 구역이 된다. 적의 몸에 배에 또 하나의 입이 있기가 있다면 삼키는 방식도 달라진다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002994/index.html"},{"id":"MEJE-KW-002995","row_version":1,"title":"낮게 날다 지면을 아슬아슬하게 스치기","original":"Belly-Scraping Flight","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"비행체가 건물이나 나무, 땅을 거의 건드리며 지나간다. 작은 접촉 하나가 추락의 가능성을 크게 느끼게 한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-002995/index.html"},{"id":"MEJE-KW-002996","row_version":2,"title":"변한 몸을 받아들이기 어려워하기","original":"Bemoaning the New Body","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"변신 뒤 자신의 모습과 감각이 낯설어진 인물이 잃은 것과 새로 가능한 것을 헤아린다. 변화에 대한 거부감이 외모만이 아니라 생활과 관계에 닿는다. 인간이 된 경우라도 인간이 아닌 존재가 인간이 되기의 새로운 몸을 익히는 과정이 남는다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002996/index.html"}]}.cards;